/bin/zsh -lc "python3 -B -c 'from itertools import permutations
from math import factorial

def encode(p):
    unused = list(range(1, len(p) + 1))
    rank = 0
    for x in p:
        rank = rank * len(unused) + unused.index(x)
        unused.remove(x)
    bits = (factorial(len(p)) - 1).bit_length()
    return format(rank, \"0%db\" % bits)

def recover(n, message):
    rank = int(message, 2)
    unused = list(range(1, n + 1))
    result = []
    for k in range(n - 1, -1, -1):
        index, rank = divmod(rank, factorial(k))
        result.append(unused.pop(index))
    return tuple(result)

total_permutations = total_pairs = 0
for n in range(3, 9):
    bits = (factorial(n) - 1).bit_length()
    seen = set()
    pair_count = 0
    for p in permutations(range(1, n + 1)):
        message = encode(p)
        assert len(message) == bits
        assert message not in seen
        seen.add(message)
        q = recover(n, message)
        source_pos = {value: i for i, value in enumerate(p)}
        decoded_pos = {value: i for i, value in enumerate(q)}
        for u in range(1, n + 1):
            for v in range(1, n + 1):
                if u "'!= v:
                    assert (source_pos[u] < source_pos[v]) == (decoded_pos[u] < decoded_pos[v])
                    pair_count += 1
    assert len(seen) == factorial(n)
    total_permutations += len(seen)
    total_pairs += pair_count
    print(f"n={n}: bits={bits}, permutations={len(seen)}, ordered_pairs={pair_count}, PASS")
print(f"TOTAL: permutations={total_permutations}, ordered_pairs={total_pairs}, PASS")
'"'"

